package session

import (
	"sync"

	"github.com/elpatron68/gotify-desktop/internal/config"
	"github.com/elpatron68/gotify-desktop/internal/stream"
)

// RuntimeStatus is the live connection state for one server.
type RuntimeStatus struct {
	ServerID  string
	Connected bool
	Error     string
}

// MessageHandler receives a Gotify stream message tagged with its server id.
type MessageHandler func(serverID string, account config.ServerAccount, msg stream.Message)

// StatusHandler is called whenever any session connection state changes.
type StatusHandler func()

// Manager runs one stream.Client per enabled server account.
type Manager struct {
	mu sync.Mutex

	OnMessage MessageHandler
	OnStatus  StatusHandler

	sessions map[string]*session
}

type session struct {
	account   config.ServerAccount
	client    *stream.Client
	connected bool
	lastErr   string
}

// New returns an empty session manager.
func New() *Manager {
	return &Manager{sessions: make(map[string]*session)}
}

// StartAll starts streams for every enabled account with a token.
func (m *Manager) StartAll(accounts []config.ServerAccount) {
	for _, acc := range accounts {
		if acc.Enabled && acc.ClientToken != "" {
			m.Start(acc)
		}
	}
}

// StopAll stops every running session.
func (m *Manager) StopAll() {
	m.mu.Lock()
	ids := make([]string, 0, len(m.sessions))
	for id := range m.sessions {
		ids = append(ids, id)
	}
	m.mu.Unlock()
	for _, id := range ids {
		m.Stop(id)
	}
}

// Start (re)starts the stream for the given account.
func (m *Manager) Start(account config.ServerAccount) {
	if account.ID == "" || account.ClientToken == "" || !account.Enabled {
		return
	}
	wsURL, err := config.StreamURL(account.ServerURL, account.ClientToken)
	if err != nil {
		m.mu.Lock()
		s := m.ensureLocked(account)
		s.connected = false
		s.lastErr = err.Error()
		m.mu.Unlock()
		m.emitStatus()
		return
	}

	m.Stop(account.ID)

	client := &stream.Client{URL: wsURL}
	serverID := account.ID
	accCopy := account
	client.OnMessage = func(msg stream.Message) {
		if m.OnMessage != nil {
			m.OnMessage(serverID, accCopy, msg)
		}
	}
	client.OnStatus = func(connected bool, errMsg string) {
		m.mu.Lock()
		s, ok := m.sessions[serverID]
		if !ok {
			m.mu.Unlock()
			return
		}
		s.connected = connected
		if errMsg != "" {
			s.lastErr = errMsg
		} else if connected {
			s.lastErr = ""
		}
		m.mu.Unlock()
		m.emitStatus()
	}

	m.mu.Lock()
	m.sessions[serverID] = &session{
		account: account,
		client:  client,
	}
	m.mu.Unlock()
	client.Start()
}

// Stop stops the stream for serverID.
func (m *Manager) Stop(serverID string) {
	m.mu.Lock()
	s, ok := m.sessions[serverID]
	if !ok {
		m.mu.Unlock()
		return
	}
	delete(m.sessions, serverID)
	client := s.client
	m.mu.Unlock()
	if client != nil {
		client.Stop()
	}
	m.emitStatus()
}

// UpdateAccount refreshes the stored account and restarts the stream if enabled.
func (m *Manager) UpdateAccount(account config.ServerAccount) {
	if !account.Enabled || account.ClientToken == "" {
		m.Stop(account.ID)
		return
	}
	m.Start(account)
}

// Snapshot returns runtime status for all known sessions plus accounts that are
// tracked. Prefer passing current config servers via StatusFor.
func (m *Manager) Snapshot() []RuntimeStatus {
	m.mu.Lock()
	defer m.mu.Unlock()
	out := make([]RuntimeStatus, 0, len(m.sessions))
	for id, s := range m.sessions {
		out = append(out, RuntimeStatus{
			ServerID:  id,
			Connected: s.connected,
			Error:     s.lastErr,
		})
	}
	return out
}

// StatusFor returns runtime status aligned to the given accounts (stable order).
func (m *Manager) StatusFor(accounts []config.ServerAccount) []RuntimeStatus {
	m.mu.Lock()
	defer m.mu.Unlock()
	out := make([]RuntimeStatus, 0, len(accounts))
	for _, acc := range accounts {
		st := RuntimeStatus{ServerID: acc.ID}
		if s, ok := m.sessions[acc.ID]; ok {
			st.Connected = s.connected
			st.Error = s.lastErr
		}
		out = append(out, st)
	}
	return out
}

// AnyConnected reports whether at least one session is connected.
func (m *Manager) AnyConnected() bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, s := range m.sessions {
		if s.connected {
			return true
		}
	}
	return false
}

// Counts returns (connected, enabledRunning) among current sessions.
func (m *Manager) Counts() (connected, total int) {
	m.mu.Lock()
	defer m.mu.Unlock()
	total = len(m.sessions)
	for _, s := range m.sessions {
		if s.connected {
			connected++
		}
	}
	return connected, total
}

// HasError reports whether any session has a non-empty last error and is down.
func (m *Manager) HasError() bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, s := range m.sessions {
		if !s.connected && s.lastErr != "" {
			return true
		}
	}
	return false
}

// LastError returns the first non-empty session error, if any.
func (m *Manager) LastError() string {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, s := range m.sessions {
		if s.lastErr != "" {
			return s.lastErr
		}
	}
	return ""
}

func (m *Manager) ensureLocked(account config.ServerAccount) *session {
	if s, ok := m.sessions[account.ID]; ok {
		s.account = account
		return s
	}
	s := &session{account: account}
	m.sessions[account.ID] = s
	return s
}

func (m *Manager) emitStatus() {
	if m.OnStatus != nil {
		m.OnStatus()
	}
}

package session

import (
	"testing"
	"time"

	"github.com/elpatron68/gotify-desktop/internal/config"
	"github.com/elpatron68/gotify-desktop/internal/stream"
)

func TestStartStopSnapshot(t *testing.T) {
	m := New()
	var msgs int
	m.OnMessage = func(serverID string, account config.ServerAccount, msg stream.Message) {
		msgs++
	}
	statusCh := make(chan struct{}, 8)
	m.OnStatus = func() {
		select {
		case statusCh <- struct{}{}:
		default:
		}
	}

	acc := config.ServerAccount{
		ID:          "s1",
		Label:       "one",
		ServerURL:   "http://127.0.0.1:1", // nothing listening
		ClientToken: "tok",
		Enabled:     true,
	}
	m.Start(acc)
	// Wait briefly for dial failure status
	select {
	case <-statusCh:
	case <-time.After(2 * time.Second):
		t.Fatal("expected status callback")
	}

	st := m.StatusFor([]config.ServerAccount{acc})
	if len(st) != 1 || st[0].ServerID != "s1" {
		t.Fatalf("%+v", st)
	}
	if m.AnyConnected() {
		t.Fatal("should not be connected")
	}
	connected, total := m.Counts()
	if total != 1 || connected != 0 {
		t.Fatalf("counts %d/%d", connected, total)
	}

	m.Stop("s1")
	connected, total = m.Counts()
	if total != 0 {
		t.Fatalf("after stop total=%d", total)
	}
}

func TestStartAllSkipsDisabled(t *testing.T) {
	m := New()
	m.StartAll([]config.ServerAccount{
		{ID: "a", ServerURL: "http://127.0.0.1:1", ClientToken: "t", Enabled: false},
		{ID: "b", ServerURL: "http://127.0.0.1:1", ClientToken: "", Enabled: true},
	})
	_, total := m.Counts()
	if total != 0 {
		t.Fatalf("total=%d", total)
	}
}

func TestUpdateAccountDisables(t *testing.T) {
	m := New()
	acc := config.ServerAccount{
		ID: "s1", ServerURL: "http://127.0.0.1:1", ClientToken: "tok", Enabled: true,
	}
	m.Start(acc)
	acc.Enabled = false
	m.UpdateAccount(acc)
	_, total := m.Counts()
	if total != 0 {
		t.Fatalf("total=%d", total)
	}
}

package main

import (
	"fmt"
	"strings"

	"github.com/elpatron68/gotify-desktop/internal/applog"
	"github.com/elpatron68/gotify-desktop/internal/config"
	"github.com/elpatron68/gotify-desktop/internal/gotifyproxy"
	"github.com/elpatron68/gotify-desktop/internal/i18n"
	"github.com/elpatron68/gotify-desktop/internal/push"
)

// ServerInfo is exposed to the frontend for the server list.
type ServerInfo struct {
	ID        string `json:"id"`
	Label     string `json:"label"`
	ServerURL string `json:"serverUrl"`
	Username  string `json:"username"`
	Enabled   bool   `json:"enabled"`
	Connected bool   `json:"connected"`
	Error     string `json:"error"`
	Active    bool   `json:"active"`
}

// ListServers returns all configured servers with runtime status.
func (a *App) ListServers() []ServerInfo {
	return a.buildServerInfos()
}

// AddServer authenticates, upserts by URL+username, starts the stream, and may set Active.
func (a *App) AddServer(serverURL, username, password, label string) (ServerInfo, error) {
	normalized, err := config.NormalizeServerURL(serverURL)
	if err != nil {
		return ServerInfo{}, err
	}
	token, err := a.auth.VerifyAndCreateClient(normalized, username, password)
	if err != nil {
		return ServerInfo{}, err
	}

	a.mu.Lock()
	wasConfigured := a.cfg.Configured()
	label = strings.TrimSpace(label)
	if label == "" {
		label = config.HostnameLabel(normalized)
	}

	var acc config.ServerAccount
	if existing := a.cfg.FindByURLUser(normalized, username); existing != nil {
		existing.ClientToken = REDACTED
		existing.Username = username
		existing.ServerURL = normalized
		existing.Enabled = true
		if strings.TrimSpace(existing.Label) == "" {
			existing.Label = label
		} else if strings.TrimSpace(label) != "" && existing.Label == config.HostnameLabel(normalized) {
			// keep existing custom label; only apply when still default hostname
		}
		// If caller passed an explicit non-empty label different from hostname default intent:
		if strings.TrimSpace(label) != "" {
			existing.Label = label
		}
		acc = *existing
	} else {
		acc = config.ServerAccount{
			ID:          config.NewServerID(),
			Label:       label,
			ServerURL:   normalized,
			Username:    username,
			ClientToken: token,
			MinPriority: 0,
			Enabled:     true,
		}
		a.cfg.Servers = append(a.cfg.Servers, acc)
	}

	if a.cfg.ActiveServerID == "" || a.cfg.FindByID(a.cfg.ActiveServerID) == nil {
		a.cfg.ActiveServerID = acc.ID
	}
	// First server ever: always make it active.
	if !wasConfigured {
		a.cfg.ActiveServerID = acc.ID
	}
	a.cfg.Normalize()
	activeID := a.cfg.ActiveServerID
	a.view = "gotify"
	a.lastErr = ""
	cfg := a.cfg
	a.mu.Unlock()

	if err := config.Save(cfg); err != nil {
		return ServerInfo{}, fmt.Errorf("save config: %w", err)
	}
	applog.Printf("add server id=%s server=%q user=%q token=%s",
		acc.ID, acc.ServerURL, acc.Username, applog.TokenFingerprint(acc.ClientToken))

	if a.sessions != nil {
		a.sessions.UpdateAccount(acc)
	}
	if activeID == acc.ID {
		a.applyActiveProxy(acc)
	}

	a.emitStatus()
	a.refreshTrayServers()
	a.updateTrayConnectionStatus()

	info := a.serverInfoFor(acc.ID)

	// Hide to tray only on first successful configure.
	if !wasConfigured {
		a.emit("show-gotify", a.gotifyPayload(acc))
		if a.window != nil {
			a.window.Hide()
		}
		applog.Printf("add server: first configure, window hidden to tray")
	} else {
		// Stay on setup for further adds; still refresh gotify if currently showing it.
		a.mu.Lock()
		view := a.view
		a.mu.Unlock()
		if view == "gotify" && activeID == acc.ID {
			a.emit("show-gotify", a.gotifyPayload(acc))
		}
	}
	return info, nil
}

// Connect is a compatibility alias for AddServer with an empty label.
func (a *App) Connect(serverURL, username, password string) error {
	_, err := a.AddServer(serverURL, username, password, "")
	return err
}

// RemoveServer stops the session and removes the account locally.
func (a *App) RemoveServer(id string) error {
	id = strings.TrimSpace(id)
	if id == "" {
		return fmt.Errorf("server id required")
	}
	a.mu.Lock()
	if !a.cfg.RemoveServer(id) {
		a.mu.Unlock()
		return fmt.Errorf("server not found")
	}
	cfg := a.cfg
	active, hasActive := a.cfg.Active()
	if !a.cfg.Configured() {
		a.view = "setup"
	}
	view := a.view
	a.mu.Unlock()

	if a.sessions != nil {
		a.sessions.Stop(id)
	}
	if err := config.Save(cfg); err != nil {
		return fmt.Errorf("save config: %w", err)
	}

	if hasActive {
		a.applyActiveProxy(active)
		if view == "gotify" {
			a.emit("show-gotify", a.gotifyPayload(active))
		}
	} else {
		_ = a.proxy.Update("", "")
		a.emit("show-setup", nil)
	}
	a.emitStatus()
	a.refreshTrayServers()
	a.updateTrayConnectionStatus()
	return nil
}

// SetActiveServer switches the embedded UI / default send target.
func (a *App) SetActiveServer(id string) error {
	id = strings.TrimSpace(id)
	a.mu.Lock()
	acc := a.cfg.FindByID(id)
	if acc == nil {
		a.mu.Unlock()
		return fmt.Errorf("server not found")
	}
	a.cfg.ActiveServerID = id
	account := *acc
	view := a.view
	cfg := a.cfg
	a.mu.Unlock()

	if err := config.Save(cfg); err != nil {
		return fmt.Errorf("save config: %w", err)
	}
	a.applyActiveProxy(account)
	a.emitStatus()
	a.refreshTrayServers()
	if view == "gotify" {
		a.emit("show-gotify", a.gotifyPayload(account))
	}
	return nil
}

// RenameServer updates the display label.
func (a *App) RenameServer(id, label string) error {
	id = strings.TrimSpace(id)
	label = strings.TrimSpace(label)
	a.mu.Lock()
	acc := a.cfg.FindByID(id)
	if acc == nil {
		a.mu.Unlock()
		return fmt.Errorf("server not found")
	}
	if label == "" {
		label = config.HostnameLabel(acc.ServerURL)
	}
	acc.Label = label
	cfg := a.cfg
	a.mu.Unlock()
	if err := config.Save(cfg); err != nil {
		return fmt.Errorf("save config: %w", err)
	}
	a.emitStatus()
	a.refreshTrayServers()
	return nil
}

// SetServerEnabled enables or disables a server stream.
func (a *App) SetServerEnabled(id string, enabled bool) error {
	id = strings.TrimSpace(id)
	a.mu.Lock()
	acc := a.cfg.FindByID(id)
	if acc == nil {
		a.mu.Unlock()
		return fmt.Errorf("server not found")
	}
	acc.Enabled = enabled
	account := *acc
	cfg := a.cfg
	a.mu.Unlock()
	if err := config.Save(cfg); err != nil {
		return fmt.Errorf("save config: %w", err)
	}
	if a.sessions != nil {
		a.sessions.UpdateAccount(account)
	}
	a.emitStatus()
	a.refreshTrayServers()
	a.updateTrayConnectionStatus()
	return nil
}

// ListApplicationsForServer lists apps on the given server.
func (a *App) ListApplicationsForServer(serverID string) ([]push.Application, error) {
	a.mu.Lock()
	acc := a.cfg.FindByID(serverID)
	if acc == nil || strings.TrimSpace(acc.ClientToken) == "" {
		a.mu.Unlock()
		return nil, fmt.Errorf("not configured")
	}
	url, token := acc.ServerURL, acc.ClientToken
	a.mu.Unlock()
	return a.push.ListApplications(url, token)
}

// SendApplicationMessageToServer sends a message via the given server.
func (a *App) SendApplicationMessageToServer(serverID string, appID uint, title, message string, priority int) error {
	a.mu.Lock()
	acc := a.cfg.FindByID(serverID)
	if acc == nil || strings.TrimSpace(acc.ClientToken) == "" {
		a.mu.Unlock()
		return fmt.Errorf("not configured")
	}
	url, token := acc.ServerURL, acc.ClientToken
	a.mu.Unlock()
	if appID == 0 {
		return fmt.Errorf("application is required")
	}
	if priority < 0 {
		priority = 0
	}
	if priority > 10 {
		priority = 10
	}
	applog.Printf("send message server=%s app=%d", serverID, appID)
	return a.push.Send(url, token, appID, title, message, priority)
}

func (a *App) applyActiveProxy(acc config.ServerAccount) {
	_ = a.proxy.Update(acc.ServerURL, acc.ClientToken)
	if _, err := a.proxy.StartWSProxy(); err != nil {
		applog.Printf("ws proxy start failed: %v", err)
	}
}

func (a *App) gotifyPayload(acc config.ServerAccount) map[string]string {
	return map[string]string{
		"serverUrl": acc.ServerURL,
		"token":     acc.ClientToken,
		"uiPath":    gotifyproxy.UIPrefix + "/",
		"serverId":  acc.ID,
		"label":     acc.Label,
	}
}

func (a *App) buildServerInfos() []ServerInfo {
	a.mu.Lock()
	servers := append([]config.ServerAccount(nil), a.cfg.Servers...)
	activeID := a.cfg.ActiveServerID
	a.mu.Unlock()

	var statuses []struct {
		id        string
		connected bool
		err       string
	}
	if a.sessions != nil {
		for _, st := range a.sessions.StatusFor(servers) {
			statuses = append(statuses, struct {
				id        string
				connected bool
				err       string
			}{st.ServerID, st.Connected, st.Error})
		}
	}
	statusByID := map[string]struct {
		connected bool
		err       string
	}{}
	for _, st := range statuses {
		statusByID[st.id] = struct {
			connected bool
			err       string
		}{st.connected, st.err}
	}

	out := make([]ServerInfo, 0, len(servers))
	for _, s := range servers {
		info := ServerInfo{
			ID:        s.ID,
			Label:     s.Label,
			ServerURL: s.ServerURL,
			Username:  s.Username,
			Enabled:   s.Enabled,
			Active:    s.ID == activeID,
		}
		if st, ok := statusByID[s.ID]; ok {
			info.Connected = st.connected
			info.Error = st.err
		}
		out = append(out, info)
	}
	return out
}

func (a *App) serverInfoFor(id string) ServerInfo {
	for _, s := range a.buildServerInfos() {
		if s.ID == id {
			return s
		}
	}
	return ServerInfo{ID: id}
}

func (a *App) refreshTrayServers() {
	if a.tray == nil {
		return
	}
	infos := a.buildServerInfos()
	entries := make([]trayServerEntry, 0, len(infos))
	for _, s := range infos {
		entries = append(entries, trayServerEntry{
			ID:     s.ID,
			Label:  s.Label,
			Active: s.Active,
		})
	}
	a.tray.SetServers(entries)
}

func (a *App) updateTrayConnectionStatus() {
	if a.tray == nil {
		return
	}
	a.mu.Lock()
	configured := a.cfg.Configured()
	a.mu.Unlock()
	if !configured {
		a.tray.SetStatus(i18n.T("tray.status_not_configured"))
		return
	}
	if a.sessions == nil {
		a.tray.SetStatus(i18n.T("tray.status_disconnected"))
		return
	}
	connected, total := a.sessions.Counts()
	switch {
	case total == 0:
		a.tray.SetStatus(i18n.T("tray.status_disconnected"))
	case connected == total:
		a.tray.SetStatus(i18n.T("tray.status_connected"))
	case connected > 0:
		a.tray.SetStatus(i18n.Tf("tray.status_partial", map[string]string{
			"Connected": fmt.Sprintf("%d", connected),
			"Total":     fmt.Sprintf("%d", total),
		}))
	case a.sessions.HasError():
		a.tray.SetStatus(i18n.T("tray.status_error"))
	default:
		a.tray.SetStatus(i18n.T("tray.status_disconnected"))
	}
}

