	}
	applog.Printf("connect saved server=%q user=%q token=%s", cfg.ServerURL, cfg.Username, applog.TokenFingerprint(cfg.ClientToken))
	_ = a.proxy.Update(cfg.ServerURL, cfg.ClientToken)
